دالة أطول_كلمة(نص) {
    متغير كلمات = افصل(نص، " ")
    متغير أطول = كلمات[٠]
    من_أجل (كلمة في كلمات) {
        إذا (طول(كلمة) > طول(أطول)) {
            أطول = كلمة
        } وإلا إذا (طول(كلمة) == طول(أطول) و كلمة < أطول) {
            أطول = كلمة
        }
    }
    ارجع أطول
}
```

